import { z } from "zod";

/**
 * What an AI chat analysis asks for and what it returns.
 *
 * Shared, unchanged, by both places an analysis can run: the cloud function
 * (analyzeChatAi.ts) and the on-device model in the browser
 * (utils/ai/localModel.ts imports this file directly). One prompt and one
 * schema means the results page cannot tell which model wrote the answer, and
 * a prompt fix lands in both. Keep it free of Node and browser APIs.
 */

export const AI_LANGUAGES = {
  en: "English",
  de: "German",
  es: "Spanish",
  fr: "French",
  pt: "Portuguese",
  it: "Italian",
} as const;

export type AiLanguage = keyof typeof AI_LANGUAGES;

/**
 * The most transcript the cloud accepts: ~130k tokens, roughly 10,000
 * messages, which is all of most chats. Kept under the 272k-token mark where
 * OpenAI's long-context pricing doubles the input rate.
 */
export const CLOUD_TRANSCRIPT_CHARS = 400_000;

/** The free preview shows one profile, which needs far less: input is ~all of its cost. */
export const PREVIEW_TRANSCRIPT_CHARS = 100_000;

/**
 * What the browser has already reduced the chat to. Participants are
 * placeholders ("Person A"), never real names: the real ones stay on the
 * device and are put back into the answer there.
 */
export interface ChatDigest {
  participants: { alias: string; messages: number }[];
  totalMessages: number;
  /** ISO dates of the first and last message. */
  firstDate: string;
  lastDate: string;
  /** Excerpts, oldest first, one "YYYY-MM-DD HH:MM alias: text" per line. */
  transcript: string;
}

/**
 * What the reader wants to know, optionally. `me` is their placeholder when
 * they said which participant they are; `question` is already anonymized.
 * `background` is what they say the chat doesn't show ("we broke up in
 * July", "she's my sister"), anonymized the same way.
 */
export interface AiAsk {
  question?: string;
  me?: string;
  background?: string;
}

export const MAX_QUESTION_CHARS = 300;
/** A few sentences: enough for who they are to each other and what happened. */
export const MAX_BACKGROUND_CHARS = 500;

const item = z.object({
  title: z.string().describe("A few words"),
  description: z
    .string()
    .describe("One or two sentences with a concrete detail from the chat"),
});

export const insightsSchema = z.object({
  answer: z
    .string()
    .describe(
      "Only if the reader asked a question: a direct, honest and kind answer in 3-6 sentences, backed by specific moments from the chat. Otherwise an empty string.",
    ),
  summary: z
    .string()
    .describe(
      "2-3 sentences: what this chat is about and its overall tone. No message counts or dates.",
    ),
  vibe: z.string().describe("A playful label for this chat, 2-4 words"),
  topics: z
    .array(item)
    .describe(
      "3-5 distinct subjects they talk about, each named after what it is about. A topic is a subject, never one person's messages.",
    ),
  people: z
    .array(
      z.object({
        name: z
          .string()
          .describe('The participant\'s placeholder exactly, e.g. "Person A"'),
        role: z
          .string()
          .describe(
            "Their role in this chat, 2-4 words, about how they take part (e.g. the planner, the joker). Never a health, psychological or diagnostic label.",
          ),
        style: z
          .string()
          .describe(
            "One sentence on how they write that sets them apart from the others",
          ),
      }),
    )
    .describe("One entry per participant, at most 8"),
  dynamics: z
    .array(item)
    .describe(
      "2-4 observations about how they interact, each about a different aspect: who initiates, balance, warmth, humour, conflict",
    ),
  highlights: z
    .array(z.string())
    .describe(
      "2-3 specific memorable, funny or touching moments, each saying what actually happened",
    ),
});

export type ChatInsights = z.infer<typeof insightsSchema>;

const overview = (digest: ChatDigest) => {
  const participants = digest.participants
    .map((p) => `- ${p.alias}: ${p.messages} messages`)
    .join("\n");
  return [
    `The chat runs from ${digest.firstDate} to ${digest.lastDate} with ${digest.totalMessages} messages.`,
    `Participants:\n${participants}`,
  ];
};

/**
 * What the reader told us that the chat doesn't show. It helps read the chat,
 * but it isn't evidence from it: quoted back as a message, it would put words
 * in someone's mouth that they never wrote.
 */
const backgroundLines = (background: string | undefined) =>
  background
    ? [
        `The reader adds background the chat itself doesn't show: "${background}"`,
        "Use this background to understand the chat. If you refer to it, say it is what the reader told you. It is not part of the chat: never quote it as a message, and never present it as something anyone said or did in the chat. Every quote, moment and highlight must come from the chat itself.",
      ]
    : [];

const askLines = (ask: AiAsk | undefined) => [
  ...(ask?.me
    ? [
        `The reader is ${ask.me}. Address them as "you" and everyone else by placeholder.`,
      ]
    : []),
  ...(ask?.question ? [`The reader asks: "${ask.question}"`] : []),
  ...backgroundLines(ask?.background),
];

/**
 * The analysis itself. Given `notes`, it works from those instead of the
 * transcript: that is how a small on-device model covers more of a chat than
 * fits in its context (see buildNotesPrompt).
 */
export function buildPrompt(
  digest: ChatDigest,
  language: AiLanguage,
  notes?: string[],
  ask?: AiAsk,
): { system: string; prompt: string } {
  const system = [
    "You analyze exported WhatsApp chats for the people who took part in them.",
    "Be specific: name concrete things that happen in the chat. No generic relationship advice.",
    "Every item must add something new. Never repeat a point, and never write the same item once per person.",
    "Be warm and a little playful, never judgmental. Do not diagnose anyone.",
    'Refer to participants only by their placeholder ("Person A", "Person B", ...), exactly as written and untranslated.',
    "Text in square brackets ([phone], [email], [link], [iban]) was removed for privacy; ignore it.",
    ...askLines(ask),
    ask?.question
      ? "Answer the reader's question in \"answer\". If the chat doesn't give enough to go on, say so honestly."
      : 'Leave "answer" empty.',
    `Write every field in ${AI_LANGUAGES[language]}.`,
  ].join("\n");

  const body = notes
    ? [
        `Notes taken while reading the chat in ${notes.length} parts, oldest first:`,
        notes.map((n, i) => `Part ${i + 1}:\n${n}`).join("\n\n"),
      ]
    : [
        "Excerpts sampled across the whole chat, oldest first:",
        digest.transcript,
      ];

  return { system, prompt: [...overview(digest), ...body].join("\n\n") };
}

/** One part of a chunked read: short notes for buildPrompt to work from. */
export function buildNotesPrompt(
  digest: ChatDigest,
  part: string,
  index: number,
  total: number,
  ask?: AiAsk,
): { system: string; prompt: string } {
  const system = [
    "You read one part of an exported WhatsApp chat and take notes for a later analysis.",
    "In at most 120 words, note: what they talk about (concrete subjects), how each participant writes and behaves, and any memorable, funny or touching moment with its date. Quote short phrases where they help.",
    ...(ask?.question
      ? [
          "Also note anything in this part that helps answer the reader's question.",
        ]
      : []),
    ...askLines(ask),
    'Refer to participants only by their placeholder ("Person A", "Person B", ...), exactly as written.',
    "Write the notes in English, as short plain sentences. No preamble.",
  ].join("\n");

  const prompt = [
    ...overview(digest),
    `Part ${index + 1} of ${total}, oldest first:`,
    part,
  ].join("\n\n");

  return { system, prompt };
}

/**
 * The reader's question on its own, as plain text. A 1B model asked for the
 * answer inside the full report filled it with the rest of the report, so
 * on device the answer is a separate, simpler call.
 */
export function buildAnswerPrompt(
  digest: ChatDigest,
  language: AiLanguage,
  notes: string[] | undefined,
  ask: AiAsk & { question: string },
): { system: string; prompt: string } {
  const { prompt } = buildPrompt(digest, language, notes);
  const system = [
    "You answer one question about an exported WhatsApp chat for someone who took part in it.",
    "Answer in 3-6 sentences: direct, honest and kind, backed by specific moments from the chat. If the chat doesn't give enough to go on, say so.",
    'Refer to participants only by their placeholder ("Person A", "Person B", ...), exactly as written and untranslated.',
    ...askLines(ask),
    `Write the answer in ${AI_LANGUAGES[language]}, as plain text without headings.`,
  ].join("\n");
  return { system, prompt };
}

/**
 * Follow-ups after a report: a conversation with a coach grounded in the
 * chat. "ask" answers the reader's questions; "reply" rewrites a draft
 * message they are about to send.
 */
export type CoachKind = "ask" | "reply";

export interface CoachTurn {
  role: "user" | "assistant";
  content: string;
}

/** One message from the reader: a question, or a draft to rewrite. */
export const MAX_COACH_CHARS = 1_000;
/** One coach answer as sent back for context. */
export const MAX_COACH_REPLY_CHARS = 2_000;
/** Turns kept per request, oldest dropped first. Odd, so it starts on the reader. */
export const MAX_COACH_TURNS = 11;

/**
 * What the model says instead of coaching when the chat or the reader's
 * message points to abuse, threats or self-harm. The page swaps it for
 * static support resources, so no model ever words that advice itself.
 */
export const COACH_SAFETY = "[SAFETY]";

/**
 * The whole coach request. `context` is the report's summary, still in
 * placeholders; it tells a small on-device model what the chat is about
 * beyond the excerpt it can fit. `background` is the reader's own, the same
 * the report was given (AiAsk).
 */
export function buildCoachPrompt(
  digest: ChatDigest,
  language: AiLanguage,
  kind: CoachKind,
  history: CoachTurn[],
  options: { me?: string; context?: string; background?: string } = {},
): { system: string; messages: CoachTurn[] } {
  const system = [
    "You are a warm, honest relationship coach. The reader took part in the WhatsApp chat below and wants help with it.",
    "Ground everything in the chat: refer to concrete moments, patterns and phrases. Don't invent things that aren't there; if the chat doesn't say, say so.",
    "Be kind but direct. Never take sides against someone who isn't here to explain themselves, and do not diagnose anyone.",
    kind === "reply"
      ? 'The reader sends a draft of a message they want to send to someone in this chat. It is not addressed to you: don\'t answer it, rewrite it. Start with the rewritten message itself: a calmer, clearer version that keeps what they mean, in their own voice and the chat\'s usual tone. Then, on a new line starting with "Why:" in the language you answer in ("Warum:", "Por qué:", "Pourquoi :", "Porquê:", "Perché:"), explain in 1-3 sentences what you changed and why, pointing at the chat\'s dynamics.'
      : "Answer the reader's questions in 3-6 sentences, as plain text without headings. End with one concrete, gentle next step when it helps.",
    `If the chat or the reader's message suggests abuse, violence, threats, coercive control, or that anyone may harm themselves, do not coach or rewrite anything: answer with exactly ${COACH_SAFETY} and nothing else.`,
    'Refer to participants only by their placeholder ("Person A", "Person B", ...), exactly as written and untranslated.',
    "Text in square brackets ([phone], [email], [link], [iban]) was removed for privacy; ignore it.",
    ...(options.me
      ? [
          `The reader is ${options.me}. Address them as "you" and everyone else by placeholder.`,
        ]
      : []),
    ...backgroundLines(options.background),
    `Write in ${AI_LANGUAGES[language]}.`,
    "",
    ...overview(digest),
    ...(options.context
      ? [`An earlier analysis said: ${options.context}`]
      : []),
    "Excerpts from the chat, oldest first:",
    digest.transcript,
  ].join("\n");
  const messages = history.slice(-MAX_COACH_TURNS);
  // A small model reads a bare draft as a message to itself and answers it
  // ("my responses might seem tailored…"), so the draft is marked as the
  // text to rewrite.
  const last = messages[messages.length - 1];
  if (kind === "reply" && last?.role === "user") {
    messages[messages.length - 1] = {
      ...last,
      content: `Draft to rewrite (to send in the chat, not to you):\n"""\n${last.content}\n"""`,
    };
  }
  return { system, messages };
}
